// src/components/CountdownTimer.js
import React, { useState, useEffect } from 'react';

const CountdownTimer = () => {
  const [timeLeft, setTimeLeft] = useState({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0
  });
  const [electionInfo, setElectionInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchElectionData();
    
    const timer = setInterval(() => {
      setTimeLeft(prevTime => {
        const { days, hours, minutes, seconds } = prevTime;
        
        if (seconds > 0) {
          return { ...prevTime, seconds: seconds - 1 };
        } else if (minutes > 0) {
          return { ...prevTime, minutes: minutes - 1, seconds: 59 };
        } else if (hours > 0) {
          return { ...prevTime, hours: hours - 1, minutes: 59, seconds: 59 };
        } else if (days > 0) {
          return { ...prevTime, days: days - 1, hours: 23, minutes: 59, seconds: 59 };
        } else {
          clearInterval(timer);
          return prevTime;
        }
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const fetchElectionData = async () => {
    try {
      const GEMINI_API_KEY = 'AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE';
      
      const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            contents: [{
              parts: [{
                text: `Provide real, accurate information about the upcoming Lok Sabha elections in India 2024. Give me:

1. Exact election dates (phases if available)
2. Current status (announced/scheduled)
3. Important deadlines (nomination, voting, results)
4. Key states and phases

Please provide this in JSON format exactly like this:
{
  "electionName": "Lok Sabha General Elections 2024",
  "electionDate": "2024-04-19",
  "phases": [
    {
      "phase": "Phase 1",
      "date": "2024-04-19",
      "states": ["Uttar Pradesh", "Bihar", "West Bengal"]
    }
  ],
  "currentStatus": "Scheduled",
  "nominationDeadline": "2024-03-30",
  "votingDeadline": "2024-04-19",
  "resultDate": "2024-06-04",
  "totalPhases": 7,
  "keyStates": ["Uttar Pradesh", "Maharashtra", "West Bengal", "Bihar"]
}

If exact dates are not announced, provide the most likely dates based on election commission patterns and news sources.`
              }]
            }],
            generationConfig: {
              temperature: 0.3,
              topK: 40,
              topP: 0.95,
              maxOutputTokens: 1024,
            }
          })
        }
      );

      if (!response.ok) {
        throw new Error(`API request failed: ${response.status}`);
      }

      const data = await response.json();
      const responseText = data.candidates[0].content.parts[0].text;
      
      // Parse JSON from response
      const jsonMatch = responseText.match(/({[\s\S]*})/);
      if (jsonMatch) {
        const electionData = JSON.parse(jsonMatch[0]);
        setElectionInfo(electionData);
        
        // Calculate countdown to first phase
        const firstPhaseDate = new Date(electionData.electionDate || electionData.phases?.[0]?.date || '2024-04-19');
        updateCountdown(firstPhaseDate);
      } else {
        throw new Error('Invalid response format');
      }
      
    } catch (error) {
      console.error('Error fetching election data:', error);
      setError('Real-time data unavailable. Showing expected schedule.');
      // Fallback data
      setElectionInfo({
        electionName: "Lok Sabha General Elections 2024",
        electionDate: "2024-04-19",
        phases: [
          {
            phase: "Phase 1",
            date: "2024-04-19",
            states: ["Uttar Pradesh", "Bihar", "West Bengal", "Tamil Nadu"]
          }
        ],
        currentStatus: "Expected Schedule",
        nominationDeadline: "2024-03-30",
        votingDeadline: "2024-04-19",
        resultDate: "2024-06-04",
        totalPhases: 7,
        keyStates: ["Uttar Pradesh", "Maharashtra", "West Bengal", "Bihar", "Tamil Nadu"]
      });
      updateCountdown(new Date('2024-04-19'));
    } finally {
      setLoading(false);
    }
  };

  const updateCountdown = (electionDate) => {
    const now = new Date().getTime();
    const distance = electionDate - now;

    if (distance < 0) {
      // Election passed, set to next expected
      const nextElection = new Date();
      nextElection.setFullYear(nextElection.getFullYear() + 5);
      const newDistance = nextElection - now;
      
      setTimeLeft({
        days: Math.floor(newDistance / (1000 * 60 * 60 * 24)),
        hours: Math.floor((newDistance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
        minutes: Math.floor((newDistance % (1000 * 60 * 60)) / (1000 * 60)),
        seconds: Math.floor((newDistance % (1000 * 60)) / 1000)
      });
      return;
    }

    setTimeLeft({
      days: Math.floor(distance / (1000 * 60 * 60 * 24)),
      hours: Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
      minutes: Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60)),
      seconds: Math.floor((distance % (1000 * 60)) / 1000)
    });
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="countdown-timer loading">
        <div className="loading-spinner"></div>
        <p>Loading real-time election data from Gemini AI...</p>
      </div>
    );
  }

  return (
    <div className="countdown-timer">
      {electionInfo && (
        <div className="election-info">
          <h3>🗳️ {electionInfo.electionName}</h3>
          <p className="election-date">
            <strong>First Phase:</strong> {formatDate(electionInfo.electionDate)}
          </p>
          <p className="election-status">
            <strong>Status:</strong> {electionInfo.currentStatus} 
            {electionInfo.totalPhases && ` • ${electionInfo.totalPhases} Phases`}
          </p>
          {electionInfo.resultDate && (
            <p className="result-date">
              <strong>Results:</strong> {formatDate(electionInfo.resultDate)}
            </p>
          )}
        </div>
      )}
      
      {error && (
        <div className="election-warning">
          <span>⚠️</span> {error}
        </div>
      )}

      <div className="countdown-grid">
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.days}</div>
          <div className="countdown-label">Days</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.hours}</div>
          <div className="countdown-label">Hours</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.minutes}</div>
          <div className="countdown-label">Minutes</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.seconds}</div>
          <div className="countdown-label">Seconds</div>
        </div>
      </div>

      {electionInfo?.phases && electionInfo.phases.length > 0 && (
        <div className="phases-info">
          <h4>Election Phases:</h4>
          <div className="phases-list">
            {electionInfo.phases.slice(0, 3).map((phase, index) => (
              <div key={index} className="phase-item">
                <strong>{phase.phase}:</strong> {formatDate(phase.date)}
                {phase.states && (
                  <span className="phase-states"> - {phase.states.slice(0, 2).join(', ')}</span>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
      
      <div className="countdown-note">
        <p>⏰ Live countdown with real-time data from Gemini AI</p>
        <p className="last-updated">Last updated: {new Date().toLocaleTimeString()}</p>
      </div>
    </div>
  );
};

export default CountdownTimer;
